from .uart_connector import UartConnector
from taf.config.testline import RU


class UartConnectorSecondary(UartConnector):
    """
    Slave class for the UART Connector.
    """

    def connect_new_rmod(self, ru: RU, alias: str, use_init_credentials: bool = False, **kwargs):
        """Setups new instance of radio connection for each UART. It gets data from RU class
        and saves it to RmodConfiguration object which supports both legacy and new RU objects creation.
        Lastly it starts new thread for given radio. If there is second port saved in RU class it will also create
        second connection for second UART port.
        After connection is opened runtime RMOD log (serial output) collection will be started.
        Args:
            ru (RU): Radio connection configuration from RU init file.
            alias (str): Name under which connection will be created.
            use_init_credentials (bool): If True, initial credentials from RU config will be used for connection.
            kwargs (dict): Additional parameters for RSI, PC host connection setup.
        """
        self.logger = self.parameters.logger
        fh_interface = self.parameters.ru_config.fh_interface
        rsi_aliases = self._rsi.setup_rmod_connection_from_ru_config(
            ru, alias, fh_interface=fh_interface, use_init_credentials=use_init_credentials, **kwargs
        )
        self.alias = rsi_aliases[0]
        self.parameters.is_connected = True
        if not self._setup_uart_connection():
            self.parameters.is_connected = False

    def take_snapshot(
        self,
        target_path_on_vm: str = None,
        reset_rmod: bool = False,
        stop_and_fix: bool = False,
        skip_downloading: bool = False,
        timeout: int = 180,
        proxy_vm_address: str = None,
        proxy_vm_username: str = None,
    ):
        self.logger.warning(
            "Snapshot triggered, but will not be executed on secondary uart. Please check for snapshot"
            f" file of {self.parameters.ru_config.serial_number} collected from the master node"
        )
        return False

    def switch_serial_to_node(self, node: int):
        self.logger.warning(f"Switching serial to node {node} is not supported with secondary uart.")
        return False

    def reset_rmod(self, wait_time: int = 100):
        self.logger.warning("Resetting RMOD is not supported with secondary uart.")
        return False

    def disconnect(self):
        """Disconnects UART connection.
        If debug logs are saved during snapshot collection, then they will be read from file to the raw serial log.
        Returns:
            None
        """
        self.parameters.is_connected = False
        self.logger.debug(f"RMOD's UART connection:{self.alias} - disconnecting request")
        self.logger.info(f"Connection teardown rmod info state: {self.rmod_info}")
        self._rsi.download_log(f"{self.parameters.log_dir}/{self.parameters.log_prefix}_raw_serial.log", self.alias)
        self._stop_thread()
        self._rsi.teardown(self.alias)
        self.logger.debug(f"RMOD's UART connection:{self.alias} - disconnected")
        self.alias = None

    def _setup_uart_connection(self):
        """
        Setups connection to single diagnostic card's UART. It starts thread for connection loop.
        Returns:
            bool: False if setting up connection or logger failed. True otherwise.
        """
        self.logger.debug(f"Logger initialized for a connection with alias:{self.alias}\n{self.parameters}")
        self.logger.info(f"Connection start rmod info state: {self.rmod_info}")
        self._confirm_node_and_serial_number()
        self._send_commands_after_connected()
        return self._start_thread_for_connection_loop()

    def _confirm_node_and_serial_number(self):
        """Confirms if the node is the node and hostname for serial number of connected RU.
        Returns:
            None
        """
        node_number = self._get_node_number()
        init_rmod_serial_number = self.parameters.ru_config.serial_number
        hw_hostname_id = self._rsi.get_rmod_serial_number(self.alias)
        if node_number is not None:
            self.logger.info(
                f"RMOD {init_rmod_serial_number} connected to SLAVE node:{node_number} "
                f"with hostname RMOD ID:{hw_hostname_id}"
            )
            self._check_for_thor_node()
        else:
            self.logger.warning(f"RMOD {init_rmod_serial_number} couldn't be verified on HW")

    def _check_for_thor_node(self):
        if "thor" in self._execute_command("hostname").lower() and self.parameters.ru_config.radio_family in [
            "Grogu",
            "Fisto",
            "Yoda",
        ]:
            self.logger.info("Connection to Thor node. Switching nodes and snapshot disabled!")
            self.parameters.second_uart = True

    def _handle_status_change_to_login_possible(self):
        self.logger.debug("Login is possible, trying to send 'pwd' command to log in")
        self._send_command("pwd")
        if self.parameters.ru_config.commands_after_login_slave:
            for command in self.parameters.ru_config.commands_after_login_slave:
                self._send_command(command)
